import outline from "./campus-outline.json";
import type { Bbox } from "@/lib/geo/distance";

/**
 * The approved campus boundary, for drawing. Generated by `npm run campus:build`
 * from data/campus.geojson; do not edit campus-outline.json by hand.
 */
export const CAMPUS_BBOX = outline.bbox as Bbox;

/** One or more polygons, each a list of rings, each a list of [lng, lat]. */
export const CAMPUS_POLYGONS = outline.polygons as [number, number][][][];

export const CAMPUS_GEOJSON = {
  type: "Feature" as const,
  properties: {},
  geometry: { type: "MultiPolygon" as const, coordinates: CAMPUS_POLYGONS },
};

/** The bounding box grown by `meters` on every side. */
export function paddedBbox(meters: number): Bbox {
  const [w, s, e, n] = CAMPUS_BBOX;
  const dLat = meters / 111_320;
  const dLng = meters / (111_320 * Math.cos((((s + n) / 2) * Math.PI) / 180));
  return [w - dLng, s - dLat, e + dLng, n + dLat];
}

/** Maps [lng, lat] into a `width` × `height` box, north up, with the right proportions for this latitude. */
function projector(width: number, height: number, padding: number) {
  const [w, s, e, n] = CAMPUS_BBOX;
  const squeeze = Math.cos((((s + n) / 2) * Math.PI) / 180);
  const spanX = (e - w) * squeeze;
  const spanY = n - s;
  const scale = Math.min((width - 2 * padding) / spanX, (height - 2 * padding) / spanY);
  const offsetX = (width - spanX * scale) / 2;
  const offsetY = (height - spanY * scale) / 2;
  return ([lng, lat]: [number, number]): [number, number] => [
    Math.round((offsetX + (lng - w) * squeeze * scale) * 10) / 10,
    Math.round((offsetY + (n - lat) * scale) * 10) / 10,
  ];
}

/** Where a place on campus falls in a `width` × `height` drawing of the outline. */
export function campusSvgPoint(lng: number, lat: number, width: number, height: number, padding = 0): [number, number] {
  return projector(width, height, padding)([lng, lat]);
}

/** The campus outline as an SVG path that fits a `width` × `height` box. */
export function campusSvgPath(width: number, height: number, padding = 0): string {
  const point = projector(width, height, padding);
  return CAMPUS_POLYGONS.flatMap((polygon) => polygon.map((ring) => `M${ring.map((p) => point(p).join(" ")).join("L")}Z`)).join("");
}
